<script setup lang="ts">
import{onMounted,ref,computed}from'vue';import{request}from'../api/request';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';import{useAuthStore}from'../stores/auth';import{displayValue}from'../utils/display';
const p=defineProps<{title:string,api:string,kind:string}>(),rows=ref<any[]>([]),loading=ref(false),total=ref(0),page=ref(1),filter=ref(''),dialog=ref(false),editing=ref<any>({}),saving=ref(false),router=useRouter(),auth=useAuthStore();
const cfg:any={'inspection/templates':{name:'templateName',create:'inspection:template:manage',edit:'inspection:template:manage',fields:['templateCode','templateName','categoryId','version','description','status']},'inspection/plans':{name:'planName',create:'inspection:plan:manage',edit:'inspection:plan:manage',fields:['planCode','planName','deviceId','templateId','scheduleType','cronExpression','assigneeUserId','status']},'inspection/tasks':{name:'taskCode',fields:['taskCode','deviceId','taskStatus','resultStatus']},'inspection/abnormals':{name:'title',fields:['abnormalCode','title','severity','status','deviceId']},'maintenance/defects':{name:'title',fields:['defectCode','title','sourceType','severity','status','deviceId']},'maintenance/work-orders':{name:'title',create:'maintenance:workorder:create',fields:['workOrderCode','title','defectId','deviceId','priority','status','assigneeUserId']},'ai/diagnoses':{name:'diagnosisCode',create:'ai:diagnosis',fields:['diagnosisCode','triggerType','riskLevel','diagnosisStatus','deviceId']},'notifications':{name:'title',fields:['notificationType','title','readStatus','createdAt']}};
const c=computed(()=>cfg[p.kind]||{});function label(k:string){return({deviceName:'设备名称',templateName:'模板名称',planName:'计划名称',taskCode:'任务编号',title:'标题',status:'状态',severity:'风险',deviceId:'设备ID',templateId:'模板ID',cronExpression:'计划表达式',triggerType:'触发类型',riskLevel:'风险等级',readStatus:'已读状态',taskStatus:'任务状态',resultStatus:'结果状态',diagnosisStatus:'诊断状态',notificationType:'通知类型'}as any)[k]||k}async function load(){loading.value=true;try{const params:any={pageNum:page.value,pageSize:20};if(['inspection/tasks','maintenance/work-orders'].includes(p.kind)&&filter.value)params.status=filter.value;const d:any=await request.get(p.api,{params});rows.value=Array.isArray(d)?d:d.records||[];total.value=d.total||rows.value.length}finally{loading.value=false}}function open(row?:any){editing.value=row?{...row}:{};dialog.value=true}async function save(){saving.value=true;try{if(p.kind==='ai/diagnoses')await request.post(p.api,{triggerType:editing.value.triggerType,triggerId:editing.value.triggerId,deviceId:editing.value.deviceId,abnormalSummary:editing.value.abnormalSummary,userDescription:editing.value.userDescription});else if(editing.value.id)await request.put(p.api+'/'+editing.value.id,editing.value);else await request.post(p.api,editing.value);ElMessage.success('保存成功');dialog.value=false;load()}finally{saving.value=false}}async function generate(id:any){await request.post('/api/inspection/plans/'+id+'/generate-task');ElMessage.success('任务已生成');load()}async function read(row:any){await request.put(p.api+'/'+row.id+'/read');row.readStatus='READ';auth.refreshUnread()}function detail(row:any){router.push('/'+p.kind+'/'+row.id)}onMounted(load)
</script>
<template><section><div class="page-head"><h1>{{title}}</h1><div><el-select v-if="kind.includes('tasks')||kind.includes('work-orders')" v-model="filter" placeholder="状态筛选" clearable @change="load"><el-option label="全部" value=""/></el-select><el-button v-if="c.create&&auth.can(c.create)" type="primary" @click="open()">新增</el-button></div></div><el-card><el-table :data="rows" v-loading="loading"><el-table-column prop="id" label="ID" width="160"/><el-table-column :prop="c.name" :label="label(c.name)" min-width="160"><template #default="x">{{displayValue(x.row[c.name])}}</template></el-table-column><el-table-column v-for="f in c.fields?.filter((x:string)=>x!==c.name).slice(1,5)" :key="f" :prop="f" :label="label(f)"><template #default="x">{{displayValue(x.row[f])}}</template></el-table-column><el-table-column label="操作" width="230"><template #default="x"><el-button v-if="kind!=='notifications'" link @click="detail(x.row)">详情</el-button><el-button v-if="c.edit&&auth.can(c.edit)" link @click="open(x.row)">编辑</el-button><el-button v-if="kind==='inspection/plans'&&auth.can('inspection:plan:manage')" link @click="generate(x.row.id)">生成任务</el-button><el-button v-if="kind==='notifications'&&x.row.readStatus!=='READ'" link @click="read(x.row)">标为已读</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!rows.length" description="暂无数据"/><el-pagination v-if="total>20" layout="prev, pager, next" :total="total" v-model:current-page="page" @current-change="load"/></el-card><el-dialog v-model="dialog" :title="editing.id?'编辑':'新增'" width="560"><el-form label-width="120"><el-form-item v-for="f in c.fields" :key="f" :label="label(f)"><el-input v-model="editing[f]"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></section></template>
